import re

def compile_sig(sig):
    # "48 8B ?? 89" -> 바이트 정규식. ?? 는 아무 바이트
    parts = [b"." if t == "??" else re.escape(bytes([int(t, 16)])) for t in sig.split()]
    return re.compile(b"".join(parts), re.DOTALL)

def scan(buf, sig):
    return [m.start() for m in compile_sig(sig).finditer(buf)]

mem = bytes.fromhex("90 90 48 8B 05 10 20 30 40 89 41 08 C3 90 48 8B 05 AA BB CC DD 89 41 08 C3".replace(" ", ""))
print(scan(mem, "48 8B 05 ?? ?? ?? ?? 89 41 08"))   # [2, 14]  주소 칸을 비우면 두 곳
print(scan(mem, "48 8B 05 10 20 30 40 89 41 08"))   # [2]      주소까지 고정하면 한 곳
